INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_mat-pocitani-do-5_0','Kolik je to prstů, když ukážeš jednu ruku?',ARRAY['2','4','10','5']::TEXT[],3,'Na jedné ruce je pět prstů.',1,ARRAY[]::TEXT[],NULL,0,'c_mat-pocitani-do-5',NULL,NOW()),
('q_mat-pocitani-do-5_1','Které číslo následuje po čísle 2?',ARRAY['4','3','5','1']::TEXT[],1,'Řada jde 1, 2, 3, 4, 5.',1,ARRAY[]::TEXT[],NULL,1,'c_mat-pocitani-do-5',NULL,NOW()),
('q_mat-pocitani-do-5_2','Které číslo je před čtyřkou?',ARRAY['3','1','5','2']::TEXT[],0,'Před čtyřkou stojí trojka.',1,ARRAY[]::TEXT[],NULL,2,'c_mat-pocitani-do-5',NULL,NOW()),
('q_mat-pocitani-do-5_3','Kolik je 1 + 1?',ARRAY['2','0','1','3']::TEXT[],0,'Jedna a ještě jedna jsou dvě.',2,ARRAY[]::TEXT[],NULL,3,'c_mat-pocitani-do-5',NULL,NOW()),
('q_mat-pocitani-do-5_4','Kolik je 2 + 2?',ARRAY['4','2','3','5']::TEXT[],0,'Dvě a dvě jsou čtyři.',2,ARRAY[]::TEXT[],NULL,4,'c_mat-pocitani-do-5',NULL,NOW()),
('q_mat-pocitani-do-5_5','Které číslo je největší: 2, 5, 3?',ARRAY['1','5','3','2']::TEXT[],1,'Pětka je z nich největší.',2,ARRAY[]::TEXT[],NULL,5,'c_mat-pocitani-do-5',NULL,NOW()),
('q_mat-pocitani-do-5_6','Kolik je 5 − 1?',ARRAY['3','5','6','4']::TEXT[],3,'Když z pěti odebereš jedno, zbudou čtyři.',3,ARRAY[]::TEXT[],NULL,6,'c_mat-pocitani-do-5',NULL,NOW()),
('q_mat-pocitani-do-5_7','Doplň řadu: 1, 2, 3, ?, 5',ARRAY['3','4','2','6']::TEXT[],1,'Mezi trojkou a pětkou chybí čtyřka.',3,ARRAY[]::TEXT[],NULL,7,'c_mat-pocitani-do-5',NULL,NOW()),
('q_mat-pocitani-do-5_8','Kolik je 3 + 2?',ARRAY['6','5','1','4']::TEXT[],1,'Tři a dvě jsou dohromady pět.',3,ARRAY[]::TEXT[],NULL,8,'c_mat-pocitani-do-5',NULL,NOW()),
('q_mat-pocitani-do-5_9','Kolik je 5 − 3?',ARRAY['3','8','1','2']::TEXT[],3,'Z pěti odebereme tři a zbydou dvě.',4,ARRAY[]::TEXT[],NULL,9,'c_mat-pocitani-do-5',NULL,NOW()),
('q_mat-pocitani-do-5_10','Doplň: 2 + ? = 5',ARRAY['2','7','4','3']::TEXT[],3,'Ke dvěma musíme přidat tři, abychom měli pět.',4,ARRAY[]::TEXT[],NULL,10,'c_mat-pocitani-do-5',NULL,NOW()),
('q_mat-pocitani-do-5_11','Kolik je 4 − 4?',ARRAY['0','1','4','8']::TEXT[],0,'Když odebereš všechno, nezbyde nic, tedy nula.',4,ARRAY[]::TEXT[],NULL,11,'c_mat-pocitani-do-5',NULL,NOW()),
('q_mat-pocitani-do-5_12','Na talíři jsou 3 koblihy a přibyly 2. Kolik jich je?',ARRAY['1','5','4','6']::TEXT[],1,'3 + 2 = 5.',5,ARRAY[]::TEXT[],NULL,12,'c_mat-pocitani-do-5',NULL,NOW()),
('q_mat-pocitani-do-5_13','Máš 5 balonků a jeden ti praskl. Kolik jich zbylo?',ARRAY['3','6','5','4']::TEXT[],3,'5 − 1 = 4.',5,ARRAY[]::TEXT[],NULL,13,'c_mat-pocitani-do-5',NULL,NOW()),
('q_mat-pocitani-do-5_14','Kolik je 1 + 2 + 2?',ARRAY['6','4','5','3']::TEXT[],2,'1 + 2 = 3 a 3 + 2 = 5.',5,ARRAY[]::TEXT[],NULL,14,'c_mat-pocitani-do-5',NULL,NOW()),
('q_mat-vice-mene-stejne_0','Máš 3 jablka a kamarád 5 jablek. Kdo jich má víc?',ARRAY['Kamarád','Nikdo','Mají stejně','Ty']::TEXT[],0,'Pět je víc než tři.',1,ARRAY[]::TEXT[],NULL,0,'c_mat-vice-mene-stejne',NULL,NOW()),
('q_mat-vice-mene-stejne_1','Které číslo je větší: 4 nebo 7?',ARRAY['4','7','Žádné','Jsou stejná']::TEXT[],1,'Sedm je větší než čtyři.',1,ARRAY[]::TEXT[],NULL,1,'c_mat-vice-mene-stejne',NULL,NOW()),
('q_mat-vice-mene-stejne_2','Které číslo je menší: 6 nebo 2?',ARRAY['6','Jsou stejná','Žádné','2']::TEXT[],3,'Dvojka je menší než šestka.',1,ARRAY[]::TEXT[],NULL,2,'c_mat-vice-mene-stejne',NULL,NOW()),
('q_mat-vice-mene-stejne_3','Které znaménko patří mezi 3 a 8: 3 ? 8',ARRAY['+','<','=','>']::TEXT[],1,'Tři je menší než osm, proto píšeme <.',2,ARRAY[]::TEXT[],NULL,3,'c_mat-vice-mene-stejne',NULL,NOW()),
('q_mat-vice-mene-stejne_4','Které znaménko patří mezi 9 a 4: 9 ? 4',ARRAY['<','>','−','=']::TEXT[],1,'Devět je větší než čtyři, proto píšeme >.',2,ARRAY[]::TEXT[],NULL,4,'c_mat-vice-mene-stejne',NULL,NOW()),
('q_mat-vice-mene-stejne_5','Které znaménko patří mezi 5 a 5: 5 ? 5',ARRAY['>','<','=','+']::TEXT[],2,'Obě čísla jsou stejná, proto píšeme =.',2,ARRAY[]::TEXT[],NULL,5,'c_mat-vice-mene-stejne',NULL,NOW()),
('q_mat-vice-mene-stejne_6','Které číslo je největší: 6, 9, 4, 8?',ARRAY['4','8','6','9']::TEXT[],3,'Devítka je ze všech největší.',3,ARRAY[]::TEXT[],NULL,6,'c_mat-vice-mene-stejne',NULL,NOW()),
('q_mat-vice-mene-stejne_7','Které číslo je nejmenší: 7, 3, 5, 6?',ARRAY['3','7','6','5']::TEXT[],0,'Trojka je ze všech nejmenší.',3,ARRAY[]::TEXT[],NULL,7,'c_mat-vice-mene-stejne',NULL,NOW()),
